/* 盒模型 */

/* 全局使用border-box（推荐） */
*, *::before, *::after {
  box-sizing: border-box;
}

/* 标准盒模型 */
.standard {
  box-sizing: content-box;
  width: 200px;
  padding: 20px;
  border: 5px solid;
  /* 实际宽度 = 200 + 20*2 + 5*2 = 250px */
}

/* 怪异盒模型 */
.border-box {
  box-sizing: border-box;
  width: 200px;
  padding: 20px;
  border: 5px solid;
  /* 实际宽度 = 200px */
}

/* BFC解决margin塌陷 */
.parent {
  overflow: hidden; /* 触发BFC */
}
.child {
  margin-top: 20px; /* 不会与parent的margin合并 */
}

/* BFC解决浮动父元素高度塌陷 */
.clearfix {
  overflow: hidden; /* 触发BFC */
}

/* 更好的clearfix */
.clearfix::after {
  content: '';
  display: table;
  clear: both;
}

/* BFC实现自适应两栏布局 */
.sidebar {
  float: left;
  width: 200px;
}
.main {
  overflow: hidden; /* 触发BFC，不与float重叠 */
}

/* display: flow-root 创建干净的BFC */
.clean-bfc {
  display: flow-root; /* 推荐方式，无副作用 */
}

/* 层叠上下文 */
.stacking {
  position: relative;
  z-index: 0; /* 创建新的层叠上下文 */
}

/* 层叠顺序（从低到高）：
   1. 层叠上下文的背景和边框
   2. z-index为负
   3. 块级盒子
   4. 浮动盒子
   5. 行内盒子
   6. z-index: 0/auto
   7. z-index为正
*/
